using System;
using UnityEngine;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Workshop {
public sealed class WorkshopEffects:MonoBehaviour {
 public TurboReleaseMode ReleaseMode{get;private set;}public int ReleaseCount{get;private set;}public float LastReleasePressure{get;private set;}public float FlameIntensity=>flame==null?0:flame.intensity;public bool SceneFading=>sceneLeaving;bool sceneLeaving,previewStopping;int queuedPreview=-1;Vector3 flameScale=new Vector3(.10f,.08f,.34f);readonly TurboReleaseGate releaseGate=new TurboReleaseGate();int resetSequence;AudioSource previewSource;AudioClip[] previewClips=new AudioClip[2];
 FinchVehicle car;WorkshopBuild build;AudioSource source;WorkshopAudioVoice voice;GameObject soundRoot;AudioClip clip;Light flame;MeshRenderer flameVisual;Material flameMaterial;float previousLoad,cooldown,loadMemory;int rate;volatile float hz=30,boost,whine,slip,volume;int popLength;volatile float popGain;public int PopCount{get;private set;}public float TurboGain=>boost;public float SuperGain=>whine;public float SquealGain=>slip;
 public void Configure(FinchVehicle vehicle,WorkshopBuild state){car=vehicle;build=state;releaseGate.Reset();voice?.CancelTransients();previousLoad=0;loadMemory=0;resetSequence=car.ResetSequence;if(source==null){rate=AudioSettings.outputSampleRate;car.GetComponent<FinchDrivingHUD>()?.UseExternalEngineAudio();soundRoot=new GameObject("Workshop audio | single source/filter");soundRoot.transform.SetParent(car.transform,false);source=soundRoot.AddComponent<AudioSource>();voice=soundRoot.AddComponent<WorkshopAudioVoice>();voice.rate=rate;voice.apex=car.PowertrainCarId=="car_apex_test";source.loop=true;source.spatialBlend=0;source.dopplerLevel=0;clip=AudioClip.Create("Workshop actual-state synthetic engine",rate,1,rate,false);source.clip=clip;source.Play();var g=new GameObject("Exhaust flame | visual only");g.transform.SetParent(car.transform,false);g.transform.localPosition=new Vector3(-.5f,.36f,-2.08f);flame=g.AddComponent<Light>();flame.color=new Color(.4f,.65f,1);flame.range=1.7f;flame.enabled=false;var volume=GameObject.CreatePrimitive(PrimitiveType.Sphere);volume.name="Brief exhaust flame visual";volume.transform.SetParent(g.transform,false);volume.transform.localPosition=new Vector3(0,0,-.12f);volume.transform.localScale=new Vector3(.10f,.08f,.34f);volume.GetComponent<Collider>().enabled=false;Destroy(volume.GetComponent<Collider>());flameVisual=volume.GetComponent<MeshRenderer>();flameMaterial=new Material(Shader.Find("Standard"));flameMaterial.color=new Color(.35f,.65f,1,.55f);flameMaterial.SetFloat("_Mode",3);flameMaterial.SetInt("_SrcBlend",(int)UnityEngine.Rendering.BlendMode.SrcAlpha);flameMaterial.SetInt("_DstBlend",(int)UnityEngine.Rendering.BlendMode.One);flameMaterial.SetInt("_ZWrite",0);flameMaterial.EnableKeyword("_ALPHABLEND_ON");flameMaterial.renderQueue=3000;flameMaterial.EnableKeyword("_EMISSION");flameMaterial.SetColor("_EmissionColor",new Color(.6f,1.4f,3));flameVisual.sharedMaterial=flameMaterial;flameVisual.enabled=false;}car.GetComponent<FinchDrivingHUD>()?.UseExternalEngineAudio();}
 public static float TireGain(bool grounded,float speed,bool burnout,float measuredSlip)=>grounded&&(speed>8||burnout)?Mathf.InverseLerp(.15f,.7f,measuredSlip)*.045f:0;
 public static bool TurboAllowed(WorkshopBuild b,float pressure,float load,bool grounded)=>b.induction!="none"&&b.induction!="roots"&&grounded&&load>.02f&&pressure>0;
 public static bool PopAllowed(WorkshopBuild b,float rpm,float previous,float load,bool grounded)=>b.sound!="road"&&b.exhaustStage>0&&grounded&&rpm>2800&&previous>.35f&&load<.15f;
 public void SetReleaseMode(TurboReleaseMode mode){ReleaseMode=mode;releaseGate.Reset();voice?.CancelTurbo();}
 public void PreviewRelease(TurboReleaseMode mode){int index=(int)mode;if(previewSource==null){var g=new GameObject("Turbo sound audition | preview only");g.transform.SetParent(transform,false);previewSource=g.AddComponent<AudioSource>();previewSource.spatialBlend=0;}if(previewClips[index]==null){var values=TurboSoundDsp.Preview(mode,AudioSettings.outputSampleRate);var clip=AudioClip.Create("Turbo audition "+mode,values.Length,1,AudioSettings.outputSampleRate,false);clip.SetData(values,0);previewClips[index]=clip;}queuedPreview=index;if(previewSource.isPlaying)previewStopping=true;else StartQueuedPreview();}
 void StartQueuedPreview(){if(queuedPreview<0||previewSource==null)return;previewSource.clip=previewClips[queuedPreview];previewSource.volume=0;previewSource.Play();queuedPreview=-1;previewStopping=false;}
 public void StopPreview(){queuedPreview=-1;previewStopping=true;}
 public void BeginSceneExit(){sceneLeaving=true;StopPreview();voice?.CancelTransients();}
 void UpdatePreview(){if(previewSource==null)return;float target=previewStopping||sceneLeaving||(!Application.isFocused&&!car.externalInput)?0:1;previewSource.volume=Mathf.MoveTowards(previewSource.volume,target,Time.unscaledDeltaTime*35);if(previewStopping&&previewSource.volume<=0){previewSource.Stop();previewStopping=false;StartQueuedPreview();}}
 void Update(){if(car==null||build==null)return;UpdatePreview();if(rate!=AudioSettings.outputSampleRate){rate=AudioSettings.outputSampleRate;voice.rate=rate;}bool audibleDriving=!car.controlsLocked&&car.playerInput&&(Application.isFocused||car.externalInput)&&!sceneLeaving;float load=car.Throttle*car.Engine.ClutchEngagement;bool grounded=car.GroundedWheels>0;hz=car.Engine.Rpm/30;volume=car.controlsLocked?.025f:.06f+.035f*load;boost=TurboAllowed(build,car.Engine.BoostBar,load,car.DrivenGroundedWheels>0)?Mathf.Clamp01(car.Engine.BoostBar)*load*.075f:0;whine=build.induction=="roots"&&grounded?load*car.Engine.Rpm/6500*.045f:0;
  float lateral=0,longitudinal=0;foreach(var wheel in car.Wheels)if(wheel.GetGroundHit(out var hit)){lateral=Mathf.Max(lateral,Mathf.Abs(hit.sidewaysSlip));longitudinal=Mathf.Max(longitudinal,Mathf.Abs(hit.forwardSlip));}float wheelSlip=Mathf.Max(lateral,longitudinal);slip=TireGain(grounded,car.SpeedKph,car.IsBurningOut,wheelSlip);voice.tireSpeed=car.SpeedKph;voice.tireCornering=lateral/(lateral+longitudinal+.001f);
  bool turbo=car.Engine.definition.IsTurbo&&build.induction!="roots";bool permitted=audibleDriving&&car.DrivenGroundedWheels>0;if(resetSequence!=car.ResetSequence){resetSequence=car.ResetSequence;releaseGate.Reset();previousLoad=0;loadMemory=0;voice.CancelTransients();if(flame!=null){flame.intensity=0;flame.enabled=false;flameVisual.enabled=false;}}float pressure=releaseGate.Step(turbo,permitted,Mathf.Clamp01(car.commandedPedal),car.Engine.BoostBar);if(pressure>0){voice.TriggerRelease(ReleaseMode,pressure,build.induction=="large"?.85f:build.induction=="twin"?1.1f:1);ReleaseCount++;LastReleasePressure=pressure;}if(!turbo||!permitted){boost=0;voice.CancelTurbo();}voice.turboRotor=car.Engine.TurboAvailability*Mathf.Lerp(.35f,1,car.Engine.Rpm/car.Engine.definition.redlineRpm);voice.turboSize=build.induction=="large"?.85f:build.induction=="twin"?1.1f:1;
  if(!audibleDriving){whine=slip=0;previousLoad=0;loadMemory=0;}voice.master=sceneLeaving||(!Application.isFocused&&!car.externalInput)?0:1;voice.hz=hz;voice.engineLoad=load;voice.exhaustStage=build.exhaustStage;voice.volume=volume;voice.boost=boost;voice.whine=whine;voice.slip=slip;cooldown=Mathf.Max(0,cooldown-Time.deltaTime);if(audibleDriving&&car.commandedPedal<=.01f&&cooldown<=0&&PopAllowed(build,car.Engine.Rpm,previousLoad,0,grounded)){popLength=rate/(build.soundStage==2?4:7);popGain=build.soundStage==2?.24f:.18f;voice.TriggerPop(popGain,popLength);PopCount++;cooldown=build.soundStage==2?.18f:.35f;if(build.sound=="flame"){flame.enabled=true;flameVisual.enabled=true;flame.intensity=build.soundStage==2?4:3;flameScale=build.soundStage==2?new Vector3(.12f,.10f,.48f):new Vector3(.10f,.08f,.34f);}}if(load>.35f){previousLoad=load;loadMemory=.4f;}else{loadMemory=Mathf.Max(0,loadMemory-Time.deltaTime);if(loadMemory<=0||car.commandedPedal<=.01f)previousLoad=0;}if(flame!=null){flame.intensity=Mathf.MoveTowards(flame.intensity,0,Time.deltaTime*18);float brightness=Mathf.Clamp01(flame.intensity/4);flameVisual.transform.localScale=flameScale*Mathf.Sqrt(brightness);flameMaterial.SetColor("_Color",new Color(.35f,.65f,1,.55f*brightness));flameMaterial.SetColor("_EmissionColor",new Color(.6f,1.4f,3)*brightness);if(flame.intensity<=0){flame.enabled=false;flameVisual.enabled=false;}}
 }
 void OnDestroy(){if(previewSource!=null)previewSource.Stop();foreach(var audition in previewClips)if(audition!=null)Destroy(audition);if(source!=null)source.Stop();if(soundRoot!=null)Destroy(soundRoot);if(clip!=null)Destroy(clip);if(flame!=null)Destroy(flame.gameObject);if(flameMaterial!=null)Destroy(flameMaterial);}
}
